import{_ as n,l as o,o as e,c as s,v as r,p as l,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"printk","description":"","frontmatter":{"title":"printk","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/printk-logging.md","filePath":"cs/printk-logging.md","lastUpdated":1789023840000}'),k={name:"cs/printk-logging.md"};function u(f,a,h,_,g,m){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="printk" tabindex="-1">printk <a class="header-anchor" href="#printk" aria-label="Permalink to &quot;printk&quot;">​</a></h1><div class="epigraph"><p>printk 把内核消息写入环形缓冲：级别、时间戳、可从 /dev/kmsg 读；它必须在几乎不能睡的上下文里仍能用。</p><footer>—— 据 Linux printk 文档；[audit](/cs/kernel-audit) 为安全日志对照</footer></div><p><a href="/cs/suspend-resume">上一课</a> 失败时常只剩串口。<a href="/cs/nmi">NMI</a> 也不能睡。缺口是 <strong>printk</strong>：环形缓冲、console、与延迟打印。观测课序从此开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>printk</code> 格式化进 <code>log_buf</code>。级别：KERN_ERR 等。缺口：锁与递归；nbcon 多 console；丢消息当缓冲满。本课不把每条格式说明符当作业。</p><p><span class="marginnote"><code>pr_debug</code> 可编译去掉。early printk 在控制台驱动前用特定硬件。对象是内核日志，不是 systemd journal 全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调用 printk → 写入 ring → 唤醒 klogd/journal。对照 <a href="/cs/skbuff">sk_buff</a>：一个包，一个字符环。对照 ftrace 后课：printk 太重不能每包用。对照 <a href="/cs/fsync">fsync</a>：kmsg 默认不持久。</p>',8)),(e(),l(d,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22printk%22%5D%20--%3E%20RING%5B%22log_buf%20%E7%8E%AF%E5%BD%A2%22%5D%0A%20%20RING%20--%3E%20CONS%5B%22console%20%E8%BE%93%E5%87%BA%22%5D%0A%20%20RING%20--%3E%20KMSG%5B%22%2Fdev%2Fkmsg%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>printk 是内核最旧的观测面，保证「还能说话」。税是锁与串口慢。不要写成 ELK 栈。与 <a href="/cs/kpti-os">KPTI</a>：用户读 kmsg 要权限。</p><p>风暴：中断里 printk 可活锁，需限速。</p><p>实现上：console_lock 曾让多核 printk 变成串行灾难，nbcon 在改这。rate limit 防止中断风暴自激。持久要靠 pstore 或用户态 journal，ring 重启即逝。 读法上只引用<a href="/cs/suspend-resume">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>printk</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 index/seq。不保证崩溃时环还在——kdump 后课。下一课低开销跟踪：ftrace。</p><p>版本字段会变，课序钉的是机制对象「printk」，不是某一主线内核的结构体名。 后课默认：内核消息进 ring buffer。静态与动态 tracepoint，下一课 ftrace。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>printk 写环形缓冲并可选打到 console。</li><li>必须能在受限上下文使用；满则丢。</li><li>ftrace 是下一课。</li><li>出处：Linux printk；kernel logging。</li></ul>',11))])}const E=n(k,[["render",u]]);export{T as __pageData,E as default};
